 static void Animations(ShieldPanel hero,Window window,string folder){
  string[] states={"idle","REQUESTED","COPY_VERIFIED","REMOVAL_CONFIRMED","RESTORED","UNCONFIRMED","SCAN_COMPLETED"};string[] wanted={"idle","handling","copy","confirmed","restored","warning","scanned"};
  for(int i=0;i<states.Length;i++){hero.Failed=false;hero.Findings=hero.Tests=0;hero.Active=i==1;hero.ActionState=states[i];hero.RefreshState();if(hero.Mode!=wanted[i])throw new Exception("Wrong action animation: "+states[i]);using(var bmp=new Bitmap(hero.Width,hero.Height)){hero.DrawToBitmap(bmp,hero.ClientRectangle);bmp.Save(Path.Combine(folder,"animation-"+wanted[i]+".png"));}}
  hero.Active=false;hero.ActionState="idle";hero.Findings=1;hero.RefreshState();if(hero.Mode!="detected"||!hero.AccessibleDescription.Contains("atitiktis"))throw new Exception("Detection visual missing");using(var bmp=new Bitmap(hero.Width,hero.Height)){hero.DrawToBitmap(bmp,hero.ClientRectangle);bmp.Save(Path.Combine(folder,"animation-detected.png"));}
  window.Activate();window.Focus();Application.DoEvents();var pulseTimer=(Timer)typeof(ShieldPanel).GetField("timer",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(hero);hero.RefreshState();if(!pulseTimer.Enabled)throw new Exception("Detection pulse did not start in focused window");byte[] frameA;using(var bmp=new Bitmap(hero.Width,hero.Height))using(var memory=new MemoryStream()){hero.DrawToBitmap(bmp,hero.ClientRectangle);bmp.Save(memory,System.Drawing.Imaging.ImageFormat.Png);frameA=memory.ToArray();}var pulseWatch=System.Diagnostics.Stopwatch.StartNew();while(pulseWatch.ElapsedMilliseconds<250){Application.DoEvents();System.Threading.Thread.Sleep(10);}using(var bmp=new Bitmap(hero.Width,hero.Height))using(var memory=new MemoryStream()){hero.DrawToBitmap(bmp,hero.ClientRectangle);bmp.Save(memory,System.Drawing.Imaging.ImageFormat.Png);if(System.Linq.Enumerable.SequenceEqual(frameA,memory.ToArray()))throw new Exception("Detection pulse frames did not change");}while(pulseWatch.ElapsedMilliseconds<3300){Application.DoEvents();System.Threading.Thread.Sleep(10);}if(pulseTimer.Enabled)throw new Exception("Result pulse exceeded its finite duration");Console.WriteLine("Detection pulse: changed rendered frames and stopped after 3 seconds.");hero.Findings=0;hero.Tests=1;hero.RefreshState();if(hero.Mode!="test"||!hero.AccessibleDescription.Contains("ne tikras virusas"))throw new Exception("EICAR misrepresented");hero.ActionState="REMOVAL_CONFIRMED";hero.Failed=true;hero.RefreshState();if(hero.Mode!="warning")throw new Exception("Failure showed confirmation");
  var animationTimer=(Timer)typeof(ShieldPanel).GetField("timer",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(hero);hero.Failed=false;hero.Tests=0;hero.Active=true;hero.ActionState="REQUESTED";hero.Motion=false;hero.RefreshState();if(animationTimer.Enabled)throw new Exception("Motion disabled but timer runs");hero.Motion=true;hero.Paused=true;hero.RefreshState();if(animationTimer.Enabled)throw new Exception("Paused timer runs");hero.Paused=false;hero.Active=false;hero.ActionState="idle";hero.RefreshState();if(animationTimer.Enabled)throw new Exception("Idle timer runs");Console.WriteLine("Animation states: action stages, detection, EICAR, failure precedence, motion-off, pause and idle timers passed.");
 }
