 static void ReadOnlyHistory(Window window,Core core){var flags=BindingFlags.Instance|BindingFlags.NonPublic;var witness=core.SessionFindings[0];typeof(Window).GetField("selected",flags).SetValue(window,witness);string report=(string)typeof(Window).GetField("lastReport",flags).GetValue(window);int count=core.SessionFindings.Count;string[] paths={Path.Combine(core.Root,"history.json"),Path.Combine(core.Root,"findings.json")};byte[][] before=Array.ConvertAll(paths,p=>File.Exists(p)?File.ReadAllBytes(p):null);foreach(string method in new[]{"HistoryView","FindingsView","ViewReport"}){bool read=false;int ticks=0;using(var timer=new Timer {Interval=100}){timer.Tick+=(s,e)=>{ticks++;foreach(Form f in Application.OpenForms){if(f==window||!f.Text.StartsWith("Istorin"))continue;foreach(Control c in f.Controls){var box=c as TextBox;if(box!=null&&box.Text!="Skaitoma…"){read=box.ReadOnly&&box.Text.Contains(method=="HistoryView"?"Istorinės kopijos":method=="FindingsView"?"Tai istoriniai įrašai":"Ataskaita neperskaityta");timer.Stop();f.Close();return;}}if(ticks>50){timer.Stop();f.Close();return;}}};timer.Start();typeof(Window).GetMethod(method,flags).Invoke(window,method=="ViewReport"?new object[]{"Istorinė skaitymo klaida",(Func<string>)(()=>{throw new IOException("fixture failure");})}:new object[0]);}if(!read||core.SessionFindings.Count!=count||!Object.ReferenceEquals(witness,typeof(Window).GetField("selected",flags).GetValue(window))||report!=(string)typeof(Window).GetField("lastReport",flags).GetValue(window))throw new Exception("History review changed live evidence");for(int i=0;i<paths.Length;i++){byte[] after=File.Exists(paths[i])?File.ReadAllBytes(paths[i]):null;if((before[i]==null)!=(after==null)||(after!=null&&!System.Linq.Enumerable.SequenceEqual(before[i],after)))throw new Exception("History review wrote persistent state");}}Console.WriteLine("Read-only history, findings and failed-read dialogs preserved selected witness, session findings, exported report and persist