 static void PowerQueue(Window window,Core core,string path){window.Activate();window.Focus();Application.DoEvents();var field=typeof(Window).GetField("folderMonitor",BindingFlags.Instance|BindingFlags.NonPublic);var line=typeof(Window).GetField("powerLine",BindingFlags.Instance|BindingFlags.NonPublic);object previous=line.GetValue(window);bool setting=core.Config.MonitorOnAc;var queue=new FolderMonitor(Path.GetDirectoryName(path),false);queue.Enqueue(path,DateTime.UtcNow.AddSeconds(-20).Ticks);field.SetValue(window,queue);core.Config.MonitorOnAc=true;try{foreach(PowerLineStatus power in new[]{PowerLineStatus.Offline,PowerLineStatus.Unknown}){line.SetValue(window,new Func<PowerLineStatus>(()=>power));typeof(Window).GetMethod("MonitorTick",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(window,new object[0]);if(queue.Count!=1)throw new Exception("Battery/unknown power consumed queued file");}line.SetValue(window,new Func<PowerLineStatus>(()=>{throw new NotSupportedException();}));typeof(Window).GetMethod("MonitorTick",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(window,new object[0]);if(queue.Count!=1)throw new Exception("Power status error consumed queued file");line.SetValue(window,new Func<PowerLineStatus>(()=>PowerLineStatus.Online));typeof(Window).GetMethod("MonitorTick",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(window,new object[0]);var watch=System.Diagnostics.Stopwatch.StartNew();while((bool)typeof(Window).GetField("busy",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(window)&&watch.ElapsedMilliseconds<10000){Application.DoEvents();System.Threading.Thread.Sleep(20);}if(queue.Count!=0||(bool)typeof(Window).GetField("busy",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(window))throw new Exception("Queued scan did not resume with AC power");Console.WriteLine("Power monitor: battery/unknown/error preserve queue; simulated AC resumes file check.");}finally{field.SetValue(window,null);queue.Dispose();line.SetValue(window,prev